function xp_input(string $name,string $label,string $type='text',string $value='',bool $required=true):void{if($type!=='password'&&isset($_POST[$name])&&is_string($_POST[$name]))$value=$_POST[$name];echo '<label>'.e($label).'<input name="'.e($name).'" type="'.e($type).'" value="'.e($value).'" '.($required?'required':'').' '.($type==='password'?'autocomplete="current-password"':'').' maxlength="'.($type==='password'?'72':'500').'" ></label>';}
function xp_select(string $name,string $label,array $options,string $selected=''):void{echo '<label>'.e($label).'<select name="'.e($name).'">';foreach($options as $id=>$text)echo '<option value="'.e($id).'"'.((is_string($_POST[$name]??null)?$_POST[$name]:$selected)===(string)$id?' selected':'').'>'.e($text).'</option>';echo '</select></label>';}
function xp_form(string $action,string $button,array $fields=[]):void{echo '<form method="post" class="xp-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="xp_action" value="'.e($action).'">';foreach($fields as $name=>$spec){[$label,$type]=$spec;if(is_array($type))xp_select($name,$label,$type,(string)($spec[2]??''));elseif($type==='check')echo '<label class="xp-check"><input type="checkbox" name="'.e($name).'" value="yes"'.(!empty($spec[2])?' checked':'').'>'.e($label).'</label>';elseif($type==='textarea')echo '<label>'.e($label).'<textarea name="'.e($name).'" rows="3" required>'.e($spec[2]??'').'</textarea></label>';else xp_input($name,$label,$type,(string)($spec[2]??''),(bool)($spec[3]??true));}echo '<button class="btn" type="submit">'.e($button).'</button></form>';}
function xp_asset_head():void{echo '<link rel="stylesheet" href="experience.css?v=510"><script src="experience.js?v=510" defer></script>';}
