lanData">'.json_encode($publicPlans,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script>';if(empty($_SESSION['xp_register_key']))$_SESSION['xp_register_key']=bin2hex(random_bytes(32));echo '<input type="hidden" name="request_key" value="'.e($_SESSION['xp_register_key']).'"><p class="xp-muted">Prices above show each cycle’s charge. Your selected plan and cycle determine checkout. A trial follows the plan; a zero-price cycle is a free subscription. Paid access is activated only after verified payment. No automatic renewal charge.</p>';}
if($join){$options=['0'=>'Choose your school, or use its private invitation code'];foreach(q('SELECT s.tenant_id,t.name,t.state FROM xp_schools s JOIN tenants t ON t.id=s.tenant_id WHERE s.listed=1 AND s.requests_enabled=1 ORDER BY t.name LIMIT 500')->fetchAll() as $s)$options[$s['tenant_id']]=$s['name'].' · '.$s['state'];xp_select('school_id','School',$options);xp_input('school_code','Private school invitation code (if supplied)','text','',false);xp_select('requested_role','I am joining as',xp_join_roles());xp_input('reference_note','School reference / relationship (do not enter sensitive child details)');}
