if($mode==='login'){echo '<section class="xp-demo"><div><span class="xp-eyebrow">TAKE SCHOOLOS FOR A SPIN</span><h3>Your next school day, in demo.</h3><p class="xp-muted">Pick a role to fill the sign-in form. Shared fictional records connect the accounts. Changes may be reset; never enter real personal data. External sending and payments are disabled.</p></div><div class="xp-demo-grid">';foreach(xp_demo_roles() as $key=>$label)echo '<button type="button" data-demo-role="'.e($key).'">'.e($label).' <span>→</span></button>';echo '</div><p id="xpDemoStatus" class="xp-muted" role="status">Demo access is available after the platform team configures the isolated sandbox.</p></section>';}
echo '<footer class="xp-account-foot">'.($school?'Start small. Build confidence. Grow together.':'SchoolOS Nigeria · A little less admin. A lot more possibility.').'</footer></div></main></div></body></html>';}
