function xp_billing_gate(array $u):void{header('Cache-Control: no-store');echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Your school subscription · SchoolOS</title>';xp_asset_head();echo '</head><body class="xp-simple"><main class="xp-panel"><a class="xp-brand" href="?login=1">School<span>OS</span></a><h1>A great school journey starts here.</h1><p>Finish your subscription to open your guided school setup. Existing records remain safe.</p>';if(isset($_SESSION['xp_notice'])){echo '<div class="xp-notice" role="status">'.e($_SESSION['xp_notice']).'</div>';unset($_SESSION['xp_notice']);}xp_billing($u);echo '<p><a href="?logout=1">Sign out</a></p></main></body></html>';}
function xp_billing(array $u):void{$s=xp_subscription($u);if(!$s){echo '<p>Your existing school account is managed by the platform’s subscription workspace.</p>';return;}echo '<div class="xp-kpis"><div><small>Your plan</small><strong>'.e($s['plan_name']).'</strong></div><div><small>Selected '.e($s['cycle']).' charge</small><strong>₦'.number_format((int)$s['price_kobo']/100,2).'</strong></div><div><small>Status</small><strong>'.e(ucfirst($s['status'])).'</strong><small>Expires '.e($s['expires_at']).' WAT</small></div></div>';if((int)$s['price_kobo']===0&&$s['expires_at']<=date('Y-m-d H:i:s'))xp_form('renew_free','Renew my configured free plan');if($s['price_kobo']>0){xp_form('checkout','Create secure Paystack checkout');$rows=q('SELECT * FROM xp_payments WHERE tenant_id=? ORDER BY id DESC LIMIT 10',[$u['tenant_id']])->fetchAll();foreach($rows as $p){echo '<div class="xp-checkout"><strong>'.e($p['reference']).'</strong><p>₦'.number_format((int)$p['amount_kobo']/100,2).' · '.e($p['status']).'</p>';if($p['checkout_url']&&$p['status']==='pending')echo '<a class="btn" href="'.e($p['checkout_url']).'" rel="noopener">Open secure checkout →</a>';if($p['status']==='pending')xp_form('verify','Verify completed payment',['payment_id'=>['Payment ID','hidden',(string)$p['id']]]);echo '</div>';}}echo '<p class="xp-muted">A browser return or bank screenshot never confirms payment. The server verifies the amount, NGN currency and unique reference. Contact the platform team if checkout is unavailable.</p>';}
function xp_tour_steps(array $u):array{if($u['role']==='school_admin')return [['Welcome to your school','This overview brings your priorities together. Start with setup, then add people and begin your school day.','#xpWelcome'],['Your setup compass','These checks explain what is missing and how it affects your records. Progress updates from real configuration.','#xpSetup'],['A clearer way to move','Use grouped navigation to open a workspace. Search by what you want to do, such as attendance or payments.','#sidebar'],['Your school day at a glance','The cards show recorded data, with clear denominators. Open a workspace to see the records behind the numbers.','#xpMetrics'],['Bring your community in','Create accounts directly or approve requests. Always verify identity, employee roles and child links before access.','#xpActions'],['Make it yours','Switch theme, check Lagos time and return to this walkthrough whenever you need a reminder.','.top']];return [['A workspace for your role','Your home page highlights the tasks and records you can access.','#xpWelcome'],['Find your next task','Use the quick actions to open your assigned workspace.','#xpActions'],['Navigate with confidence','Search your menu and open a workspace. Your account role and school assignments determine access.','#sidebar'],['Your day, your view','The date and clock use Africa/Lagos. Change theme and replay this guide from the header.','.top']];}
function xp_shell(array $u):void{xp_asset_head();echo '<div class="xp-topbar"><a href="?page=documentation">Help & role guides ↗</a><a href="?page=affiliate-account">Website & Affiliates ↗</a></div>';echo '<div class="xp-topbar"><span>YOUR CONNECTED SCHOOL DAY</span>';xp_clock();echo '<button class="theme-toggle" type="button" data-xp-tour>✦ Take a walkthrough</button></div>';if(defined('SCHOOLOS_DEMO_MODE'))echo '<div class="xp-notice" role="status">DEMO SANDBOX · Fictional shared records. Please do not enter real personal data. External payments, AI and messages are disabled. <a href="?logout=1">Switch role</a></div>';if(isset($_SESSION['xp_notice'])){echo '<div class="xp-notice" role="status">'.e($_SESSION['xp_notice']).'</div>';unset($_SESSION['xp_notice']);}$done=false;if(xp_ready()){$done=g('SELECT step FROM xp_progress WHERE tenant_id=? AND user_id=? AND step=?',[(int)($u['tenant_id']??0),$u['id'],'tour']);}$done=$done||!empty($_SESSION['xp_tour_done']);echo '<script type="application/json" id="xpTourData">'.json_encode(['steps'=>xp_tour_steps($u),'first'=>xp_ready()&&!$done,'role'=>$u['role']],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script>';}
function xp_links(array $u):array{$role=$u['role'];if($role==='school_admin')return [['Add & organize students','students','People'],['Record attendance','attendance','School day'],['Manage fees & receipts','fees','Finance'],['Review access requests','welcome&view=access','Community'],['Plan the school year','school_setup','School setup'],['View school analytics','intelligence','Insights']];if($role==='platform_super_admin')return [['Schools & subscriptions','saas','Platform'],['School provisioning','platform','Schools'],['Experience configuration','welcome&view=platform','Setup'],['Verified updates','system','Release manager']];if($role==='teacher')return [['My classes','learning&view=classes','Teaching'],['Take attendance','learning&view=attendance','School day'],['Enter assessments','learning&view=scores','Academics'],['Homework & assignments','learning&view=assignments','Teaching']];if($role==='parent')return [['My children','family','Family'],['Fees & receipts','family&view=payments','Finance'],['School messages','services&area=engagement&view=messages','Community'],['Pickup authorizations','intelligence&area=innovations&view=pickup','Safety']];if($role==='student')return [['My learning','learning&view=dashboard','Learning'],['Homework','learning&view=homework','Study'],['My grades','learning&view=grades','Progress'],['Study planner','learning&view=planner','My day']];if($role==='staff'){$links=[];foreach([['driver','Driver manifest','operations&area=transport','Transport'],['warden','Warden workspace','operations&area=boarding','Boarding'],['hr_manager','Staff & payroll','operations&area=hr','People']] as [$cap,$name,$url,$tag])if(op_can($u,$cap))$links[]=[$name,$url,$tag];foreach([['librarian','Library desk','services&area=library','Library'],['stock_manager','Stock & school store','services&area=inventory','Inventory'],['communications_manager','Announcements & messages','services&area=engagement','Community']] as [$cap,$name,$url,$tag])if(sv_can($u,$cap))$links[]=[$name,$url,$tag];$links[]=['My tasks','tasks','My day'];$links[]=['Support','support','Help'];return $links;}return $role==='admissions'?[['Admissions applications','applications','Admissions'],['My tasks','tasks','My day']]:[['Partner referrals','referrals','Partnerships'],['Support','support','Help']];}
function xp_checks(array $u):array{if($u['role']!=='school_admin')return [];$tid=(int)$u['tenant_id'];$checks=[];$add=function($key,$title,$why,$url,$done)use(&$checks){$checks[]=['key'=>$key,'title'=>$title,'why'=>$why,'url'=>$url,'done'=>(bool)$done];};$add('identity','School identity & branding','Confirm school details so families recognize your documents and workspace.','school_setup&step=branding',xp_has('school_setup_records')&&g("SELECT id FROM school_setup_records WHERE tenant_id=? AND module_key='branding' AND active=1",[$tid]));$add('classes','Classes, subjects & current session','Class and session assignments determine attendance and published results.','school_setup',g('SELECT id FROM classes WHERE tenant_id=? AND session_name IS NOT NULL AND session_name<>\'\' LIMIT 1',[$tid])&&g('SELECT id FROM subjects WHERE tenant_id=? LIMIT 1',[$tid]));$add('students','Student records','Add students and place them in classes before attendance and fees.','students',g('SELECT id FROM students WHERE tenant_id=? LIMIT 1',[$tid]));$add('allocations','Teacher assignments','Teachers only see classes and subjects assigned to them for the current session.','academics',xp_has('ac_allocations')&&g('SELECT id FROM ac_allocations WHERE tenant_id=? LIMIT 1',[$tid]));$add('links','Family and student account links','An approved account still needs verified links to see the correct child’s records.','portal_links',xp_has('ecosystem_links')&&g("SELECT id FROM ecosystem_links WHERE tenant_id=? AND relation_type IN ('parent','student') LIMIT 1",[$tid]));$add('finance','Finance configuration','Review school fee rules, payment methods and receipts before issuing bills.','fees',xp_has('fn_fee_rules')&&g('SELECT id FROM fn_fee_rules WHERE tenant_id=? LIMIT 1',[$tid]));$add('modules','Installed school workspaces','Activate the installed workspace tables before asking people to use them.','welcome',function_exists('ix_ready')&&ix_ready()&&sv_ready()&&op_ready()&&lp_ready());$add('privacy','School privacy review','Document child-data purposes, lawful bases and retention before broad rollout.','intelligence&area=governance&view=privacy',xp_has('gv_processing')&&g("SELECT id FROM gv_processing WHERE tenant_id=? AND status='approved' LIMIT 1",[$tid]));return $checks;}
function xp_workspace(array $u):void{global $schoolIdentity;$tid=(int)($u['tenant_id']??0);$name=explode(' ',trim($u['name']))[0];$school=$tid?(string)g('SELECT name FROM tenants WHERE id=?',[$tid]):'SchoolOS headquarters';echo '<section class="xp-welcome" id="xpWelcome"><div>';if(!empty($schoolIdentity['logo']))echo '<img class="xp-school-logo" src="'.e($schoolIdentity['logo']).'" alt="'.e($school).' school logo">';echo '<span class="xp-eyebrow">A LITTLE CLARITY. A LOT OF POSSIBILITY.</span><h1>Good '.(date('G')<12?'morning':(date('G')<17?'afternoon':'evening')).', '.e($name).'<span class="xp-wave">✦</span></h1><p>Welcome to '.e($school).'. Let’s make today a little easier.</p><div class="xp-pills"><span>◈ '.e(str_replace('_',' ',$u['role'])).'</span><span>◎ Connected school workspace</span></div></div><div class="xp-day"><span>'.e(date('l')).'</span><strong>'.e(date('d')).'</strong><span>'.e(date('F Y')).'</span></div></section>';
if(defined('SCHOOLOS_DEMO_MODE'))echo '<details class="xp-panel"><summary>Try a connected school day</summary><ol><li>As Teacher, record fictional attendance for Amara Demo. Switch to Parent to see it for the same child.</li><li>As Student, open the fractions homework or take the short practice CBT. Explore the Teacher workspace to review learner work.</li><li>As Driver, record a pickup from the Sunrise route; explore the linked transport information as Parent.</li><li>As Librarian, issue the existing learner request; review the same loan from the Student account.</li><li>As Communications, draft a website news item; use School reviewer for independent approval.</li></ol><p>School reviewer is a separate fictional school administrator for approval workflows. Shared demo changes can be reset. External providers, uploads and permission changes are disabled.</p></details>';if($u['role']==='school_admin'){echo '<section class="xp-panel" id="xpSetup"><div class="xp-section-head"><div><span class="xp-eyebrow">YOUR SETUP COMPASS</span><h2>Build a confident foundation.</h2></div><a href="?s=welcome" class="btn">Continue setup →</a></div>';$checks=xp_checks($u);$complete=count(array_filter($checks,fn($r)=>$r['done']));echo '<div class="xp-progress"><span style="width:'.($complete/count($checks)*100).'%"></span></div><p>'.e($complete.' of '.count($checks)).' readiness checks complete. These checks guide setup; they are not a certification of data accuracy.</p><div class="xp-alert-grid">';$pending=array_values(array_filter($checks,fn($r)=>!$r['done']));foreach(array_slice($pending,0,3) as $r)echo '<a class="xp-setup-alert" href="?s='.e($r['url']).'"><span>→</span><strong>'.e($r['title']).'</strong><small>'.e($r['why']).'</small></a>';if(!$pending)echo '<div class="xp-notice">Your core checks are complete. Keep reviewing assignments, configuration and privacy as your school changes.</div>';echo '</div></section>';}
if(in_array($u['role'],['parent','student'],true)&&!op_children($u))echo '<div class="xp-notice" role="status">A verified student link is still needed. Ask your school administrator to connect your account to the correct learner record. Your account alone does not open any child’s data.</div>';$risks=xp_risks($u);if($risks){echo '<section class="xp-panel" role="region" aria-label="Priority setup alerts"><span class="xp-eyebrow">IMPORTANT SETUP CHECKS</span><h2>A few things need your attention.</h2><div class="xp-alert-grid">';foreach($risks as [$title,$why,$url])echo '<a class="xp-setup-alert" href="?s='.e($url).'"><span>!</span><strong>'.e($title).'</strong><small>'.e($why).'</small></a>';echo '</div></section>';}echo '<section id="xpMetrics" class="xp-kpis">';$metrics=[];if($u['role']==='school_admin'){$recorded=(int)g('SELECT COUNT(*) FROM attendance WHERE tenant_id=? AND attendance_date=CURRENT_DATE()',[$tid]);$present=(int)g("SELECT COUNT(*) FROM attendance WHERE tenant_id=? AND attendance_date=CURRENT_DATE() AND status IN ('present','late')",[$tid]);$debt=xp_has('fn_invoices')?(int)g('SELECT COALESCE(SUM(GREATEST(0,amount_kobo-discount_kobo+penalty_kobo-paid_kobo)),0) FROM fn_invoices WHERE tenant_id=?',[$tid]):0;$metrics=[['Students',(int)g('SELECT COUNT(*) FROM students WHERE tenant_id=?',[$tid]),'Current school records','students'],['Attendance today',$recorded?round($present/$recorded*100).'%':'—',$present.' present/late of '.$recorded.' recorded','attendance'],['Outstanding fees','₦'.number_format($debt/100),'Current unpaid invoice balance','fees'],['Access requests',xp_has('xp_requests')?(int)g("SELECT COUNT(*) FROM xp_requests WHERE tenant_id=? AND status='pending'",[$tid]):0,'Awaiting your identity and role review','welcome&view=access']];}elseif($u['role']==='platform_super_admin')$metrics=[['Schools',(int)g('SELECT COUNT(*) FROM tenants'),'All registered school records','platform'],['Active accounts',(int)g('SELECT COUNT(*) FROM users WHERE active=1'),'Platform and school users','portal_users']];elseif(in_array($u['role'],['parent','student'],true)){foreach(op_children($u) as $child)$metrics[]=['Linked learner',$child['name'],$child['student_no']??'Verified school account link',$u['role']==='parent'?'family&child='.$child['id']:'learning'];}elseif($u['role']==='teacher')$metrics=[['Assigned classes',(int)g('SELECT COUNT(DISTINCT a.class_id) FROM ac_allocations a JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id AND c.session_name=a.session_name WHERE a.tenant_id=? AND a.teacher_id=?',[$tid,$u['id']]),'Current session teaching allocations','learning&view=classes']];else$metrics=[['Open tasks',xp_has('ecosystem_tasks')?(int)g("SELECT COUNT(*) FROM ecosystem_tasks WHERE tenant_id=? AND assigned_user_id=? AND status='open'",[$tid,$u['id']]):0,'Assigned to your account','tasks']];foreach($metrics as [$label,$value,$note,$url])echo '<a href="?s='.e($url).'"><small>'.e($label).'</small><strong>'.e($value).'</strong><small>'.e($note).'</small><span>View details →</span></a>';echo '</section>';xp_infographics($u);echo '<section class="xp-panel" id="xpActions"><div class="xp-section-head"><div><span class="xp-eyebrow">LESS SEARCHING. MORE DOING.</span><h2>Where would you like to begin?</h2></div><button class="theme-toggle" type="button" data-xp-tour>Show me around ✦</button></div><div class="xp-action-grid">';foreach(xp_links($u) as [$label,$url,$tag])echo '<a href="?s='.e($url).'"><span class="xp-action-icon">'.e(match($tag){'Finance'=>'₦','Teaching','Learning'=>'+','Safety'=>'✓',default=>'→'}).'</span><small>'.e($tag).'</small><h3>'.e($label).'</h3><span>Open workspace →</span></a>';echo '</div></section><section class="xp-bottom-grid"><div class="xp-panel"><span class="xp-eyebrow">A GOOD HABIT FOR TODAY</span><h2>Small checks. Better school days.</h2><p>'.e(match($u['role']){'school_admin'=>'Confirm the current session and teacher assignments before collecting attendance or publishing reports.','teacher'=>'Capture attendance consistently. Recorded observations make conversations with families more useful.','parent'=>'Review your linked children and contact the school if a relationship or record needs correcting.','student'=>'Break one homework task into a small next step and add it to your study planner.',default=>'Keep notes factual, use your assigned workspace and ask your school administrator when a record needs review.'}).'</p></div><div class="xp-panel"><span class="xp-eyebrow">CONNECTED, WITH CARE</span><h2>People before paperwork.</h2><p>SchoolOS connects teaching, families and school operations. Your permissions determine which records you can see and change.</p><a href="?s='.($u['role']==='student'?'learning&amp;view=feedback':'support').'">'.($u['role']==='student'?'Need a hand? Speak with your teacher or review feedback →':'Need a hand? Open support →').'</a></div></section>';}
function xp_infographics(array $u):void{$tid=(int)($u['tenant_id']??0);if(!$tid||!in_array($u['role'],['school_admin','teacher','parent','student'],true))return;$params=[$tid];$scope='';$days=$u['role']==='school_admin'||$u['role']==='teacher'?0:30;if($u['role']==='teacher'){$scope=' AND EXISTS(SELECT 1 FROM ac_allocations x JOIN classes c ON c.id=x.class_id AND c.tenant_id=x.tenant_id AND c.session_name=x.session_name WHERE x.tenant_id=s.tenant_id AND x.class_id=s.class_id AND x.teacher_id=?)';$params[]=$u['id'];}elseif(in_array($u['role'],['parent','student'],true)){$children=op_children($u);if(!$children)return;$ids=array_column($children,'id');$scope=' AND s.id IN ('.implode(',',array_fill(0,count($ids),'?')).')';$params=array_merge($params,$ids);}$where=$days?'a.attendance_date BETWEEN DATE_SUB(CURRENT_DATE(),INTERVAL 29 DAY) AND CURRENT_DATE()':'a.attendance_date=CURRENT_DATE()';$rows=q("SELECT a.status,COUNT(*) n FROM attendance a JOIN students s ON s.id=a.student_id AND s.tenant_id=a.tenant_id WHERE a.tenant_id=? AND $where $scope GROUP BY a.status",$params)->fetchAll();$counts=[];foreach($rows as $r)$counts[$r['status']]=(int)$r['n'];$recorded=array_sum($counts);$present=($counts['present']??0)+($counts['late']??0);$percent=$recorded?round(100*$present/$recorded):0;echo '<section class="xp-chart-grid"><article class="xp-panel"><span class="xp-eyebrow">'.($days?'LAST 30 DAYS':'TODAY').' · RECORDED ATTENDANCE</span><h2>Every school day counts.</h2><div class="xp-chart-content"><div class="xp-donut" style="--xp-percent:'.$percent.'" role="img" aria-label="'.e($recorded?$percent.' percent present or late, among '.$recorded.' recorded entries':'No attendance recorded').'"><div><strong>'.($recorded?$percent.'%':'—').'</strong><small>'.($recorded?'present / late':'no records').'</small></div></div><div class="xp-legend"><p><i></i> Present / late <strong>'.$present.'</strong></p><p><i class="amber"></i> Absent <strong>'.($counts['absent']??0).'</strong></p><p><i class="slate"></i> Other recorded states <strong>'.max(0,$recorded-$present-($counts['absent']??0)).'</strong></p><small>'.$recorded.' recorded entries. Unrecorded days are not counted as absence.</small></div></div></article><article class="xp-panel">';if(in_array($u['role'],['school_admin','parent','student'],true)&&xp_has('fn_invoices')){$invoiceParams=[$tid];$filter='';if($u['role']!=='school_admin'){$ids=array_column(op_children($u),'id');$filter=' AND student_id IN ('.implode(',',array_fill(0,count($ids),'?')).')';$invoiceParams=array_merge($invoiceParams,$ids);}$r=q('SELECT COALESCE(SUM(GREATEST(0,amount_kobo-discount_kobo+penalty_kobo)),0) billed,COALESCE(SUM(LEAST(paid_kobo,GREATEST(0,amount_kobo-discount_kobo+penalty_kobo))),0) paid FROM fn_invoices WHERE tenant_id=?'.$filter,$invoiceParams)->fetch();$billed=(int)$r['billed'];$paid=(int)$r['paid'];$pct=$billed?min(100,round(100*$paid/$billed)):0;echo '<span class="xp-eyebrow">CURRENT INVOICE POSITION</span><h2>A clearer picture of fees.</h2><div class="xp-finance-total">₦'.number_format(max(0,$billed-$paid)/100).'<small>remaining on current invoices</small></div><div class="xp-progress" role="img" aria-label="'.$pct.' percent of current net invoiced value allocated"><span style="width:'.$pct.'%"></span></div><div class="xp-chart-labels"><span>Allocated<br><strong>₦'.number_format($paid/100).'</strong></span><span>Net invoiced<br><strong>₦'.number_format($billed/100).'</strong></span></div><p>Allocations include confirmed payments and credits. This is not a bank balance or a historical cash collection figure.</p>';}else{echo '<span class="xp-eyebrow">YOUR TEACHING WEEK</span><h2>A little balance. More focus.</h2><div class="xp-week-bars">';$rows=q('SELECT weekday,COUNT(*) periods FROM ac_timetable t JOIN classes c ON c.id=t.class_id AND c.tenant_id=t.tenant_id AND c.session_name=t.session_name WHERE t.tenant_id=? AND t.teacher_id=? GROUP BY weekday',[$tid,$u['id']])->fetchAll();$periods=[];foreach($rows as $r)$periods[$r['weekday']]=(int)$r['periods'];$max=max(1,...array_values($periods));foreach([1=>'Mon',2=>'Tue',3=>'Wed',4=>'Thu',5=>'Fri',6=>'Sat',7=>'Sun'] as $day=>$name)echo '<div><strong>'.($periods[$day]??0).'</strong><i style="height:'.(($periods[$day]??0)/$max*80).'px"></i><small>'.$name.'</small></div>';echo '</div><p>Current-session timetable periods. Counts show assigned periods, not lesson completion.</p>';}echo '</article></section>';}
function xp_risks(array $u):array{if($u['role']!=='school_admin')return [];$tid=(int)$u['tenant_id'];$risks=[];$unplaced=(int)g('SELECT COUNT(*) FROM students s LEFT JOIN classes c ON c.id=s.class_id AND c.tenant_id=s.tenant_id WHERE s.tenant_id=? AND c.id IS NULL',[$tid]);if($unplaced)$risks[]=[$unplaced.' learners need a valid class','Class placement affects attendance, teaching access and results.','students'];if(xp_has('ecosystem_links')){$unlinked=(int)g("SELECT COUNT(*) FROM users u WHERE u.tenant_id=? AND u.active=1 AND u.role IN ('parent','student') AND NOT EXISTS(SELECT 1 FROM ecosystem_links l JOIN students s ON s.id=l.student_id AND s.tenant_id=l.tenant_id WHERE l.tenant_id=u.tenant_id AND l.user_id=u.id AND l.relation_type=u.role)",[$tid]);if($unlinked)$risks[]=[$unlinked.' family/student accounts need verified links','Approval alone does not connect a person to the right child.','portal_links'];}if(xp_has('ac_allocations')){$unassigned=(int)g("SELECT COUNT(*) FROM users u WHERE u.tenant_id=? AND u.active=1 AND u.role='teacher' AND NOT EXISTS(SELECT 1 FROM ac_allocations a JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id AND c.session_name=a.session_name WHERE a.tenant_id=u.tenant_id AND a.teacher_id=u.id)",[$tid]);if($unassigned)$risks[]=[$unassigned.' teachers need current-session assignments','Teachers cannot access unassigned classes or enter their scores.','academics'];}$sub=xp_subscription($u);if($sub&&strtotime($sub['expires_at'])<time()+7*86400)$risks[]=['Subscription expires within seven days','Review the subscription to avoid interrupted access.','welcome&view=billing'];return $risks;}
